private typealias T = Map<String, String>

private fun t(en: String, de: String, es: String, fr: String, hi: String, id: String, pt: String, ar: String): T =
    mapOf("en" to en, "de" to de, "es" to es, "fr" to fr, "hi" to hi, "id" to id, "pt" to pt, "ar" to ar)

private fun q(id: Int, text: T, right: Int, vararg answers: T) = Question(
    id = id,
    texts = text,
    rightAnswerId = right,
    answers = answers.mapIndexed { index, answer -> Answer(index + 1, answer) },
)

